function applyHistoricalScoreData(data, source, reconstructed) {
  if(data.competitionId!==source.id) return data;
  const rankColumn=data.headers.findIndex(value=>value==='排名'||value==='名次');
  if(data.rows.length!==source.players.length) throw new Error('Historical source changed');
  for(const [rank,,points,name,stages] of source.players) {
    const row=data.rows.find(value=>value.cells[3].text===name);
    if(!row || Number(row.cells[2].text)!==points || ![rank,Number(reconstructed.rows.find(value=>value.cells[3].text===name).cells[1].text)].includes(Number(row.cells[rankColumn].text)) || JSON.stringify(row.cells.slice(4).map(value=>value.text))!==JSON.stringify(stages.map(value=>value==='dnf'?'DNF':String(value)))) throw new Error('Historical source changed: '+name);
  }
  return {...data,headers:reconstructed.headers,rows:reconstructed.rows,history:reconstructed.history,historySource:reconstructed.historySource};
}
